import { useState } from "react";
import { AppShell } from "@/components/shell/AppShell";
import { TaskList } from "@/components/tasks/TaskList";
import { Badge } from "@/components/ui/badge";
import { countOpen, newTask, SAMPLE_TASKS, type Task } from "@/lib/tasks";

// The home page ("/"): Acme Inc's task list.
export default function App() {
  const [tasks, setTasks] = useState<Task[]>(SAMPLE_TASKS);

  const add = (title: string) => setTasks((all) => [newTask(title), ...all]);
  const toggle = (id: string) =>
    setTasks((all) => all.map((t) => (t.id === id ? { ...t, status: t.status === "done" ? "open" : "done" } : t)));
  const remove = (id: string) => setTasks((all) => all.filter((t) => t.id !== id));

  // How many tasks are still open, for the badge next to the heading.
  const done = tasks.length - countOpen(tasks);
  const openCount = countOpen(tasks);

  return (
    <AppShell>
      <div className="mb-8 flex flex-col gap-2">
        <p className="label-caps">Acme Inc</p>
        <div className="flex items-center gap-3">
          <h1 className="text-28 font-semibold tracking-tight">Tasks</h1>
          <Badge>{openCount} open</Badge>
        </div>
        <p className="max-w-lg text-15 text-muted-foreground">
          What the Acme team is working on this week. {done} done so far.
        </p>
      </div>
      <TaskList tasks={tasks} onAdd={add} onToggle={toggle} onRemove={remove} />
    </AppShell>
  );
}

// Acme Inc's tasks. Sample data, made up, kept in memory for now.

export type TaskStatus = "open" | "done";

export interface Task {
  id: string;
  title: string;
  owner: string;
  /** ISO date, "2026-10-28" */
  due: string;
  status: TaskStatus;
}

export const SAMPLE_TASKS: Task[] = [
  { id: "t1", title: "Send the Q4 pricing deck to the sales team", owner: "Priya", due: "2026-10-27", status: "open" },
  { id: "t2", title: "Review the onboarding emails", owner: "Marco", due: "2026-10-28", status: "open" },
  { id: "t3", title: "Book the offsite venue", owner: "Dana", due: "2026-10-30", status: "open" },
  { id: "t4", title: "Close out the September invoices", owner: "Sam", due: "2026-10-24", status: "done" },
  { id: "t5", title: "Draft the support handbook outline", owner: "Priya", due: "2026-11-02", status: "open" },
];

let counter = 100;

/** A new open task, due in a week, owned by "You". */
export function newTask(title: string, owner = "You"): Task {
  const due = new Date(Date.now() + 7 * 86_400_000).toISOString().slice(0, 10);
  counter += 1;
  return { id: `t${counter}`, title: title.trim(), owner, due, status: "open" };
}

export function countOpen(tasks: Task[]): number {
  return tasks.filter((t) => t.status === "open").length;
}

/** "Oct 27" */
export function formatDue(iso: string): string {
  return new Date(`${iso}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

import { Check, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatDue, type Task } from "@/lib/tasks";
import { cn } from "@/lib/utils";

export function TaskItem({ task, onToggle, onRemove }: { task: Task; onToggle: () => void; onRemove: () => void }) {
  const done = task.status === "done";
  return (
    <li className="group flex items-center gap-3 px-3 py-2.5">
      <button
        type="button"
        onClick={onToggle}
        aria-label={done ? "Mark as open" : "Mark as done"}
        className={cn(
          "flex size-4 shrink-0 items-center justify-center rounded-sm border border-border-strong transition-colors",
          done && "border-foreground bg-foreground text-background",
        )}
      >
        {done && <Check className="size-3" strokeWidth={3} />}
      </button>
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className={cn("truncate text-13", done && "text-muted-foreground line-through")}>{task.title}</span>
        <span className="text-11 text-muted-foreground">
          {task.owner} · due {formatDue(task.due)}
        </span>
      </div>
      <Button variant="ghost" size="icon" aria-label="Delete task" onClick={onRemove} className="opacity-0 group-hover:opacity-100">
        <Trash2 />
      </Button>
    </li>
  );
}

import { useState, type FormEvent } from "react";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import type { Task } from "@/lib/tasks";
import { TaskItem } from "./TaskItem";

type Filter = "all" | "open" | "done";

export function TaskList({
  tasks,
  onAdd,
  onToggle,
  onRemove,
}: {
  tasks: Task[];
  onAdd: (title: string) => void;
  onToggle: (id: string) => void;
  onRemove: (id: string) => void;
}) {
  const [title, setTitle] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const shown = tasks.filter((t) => filter === "all" || t.status === filter);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onAdd(title);
    setTitle("");
  };

  return (
    <Card className="overflow-hidden">
      <form onSubmit={submit} className="hairline-b flex items-center gap-2 p-3">
        <Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Add a task for the team" aria-label="New task" />
        <Button type="submit" disabled={!title.trim()}>
          <Plus /> Add
        </Button>
      </form>
      <div className="hairline-b flex items-center gap-1 px-3 py-2">
        {(["all", "open", "done"] as const).map((f) => (
          <Button key={f} size="sm" variant={filter === f ? "outline" : "ghost"} onClick={() => setFilter(f)}>
            {f === "all" ? "All" : f === "open" ? "Open" : "Done"}
          </Button>
        ))}
      </div>
      {shown.length === 0 ? (
        <EmptyState title="Nothing here" description="Tasks you add show up in this list." />
      ) : (
        <ul className="divide-y divide-border">
          {shown.map((t) => (
            <TaskItem key={t.id} task={t} onToggle={() => onToggle(t.id)} onRemove={() => onRemove(t.id)} />
          ))}
        </ul>
      )}
    </Card>
  );
}

