import { Hono } from "hono";
import type { AppEnv } from "./env";
import { one, requireUser } from "./one";
import { gmail } from "./one/actions.gen";

// Acme Inc inbox: the latest Gmail threads and a reply, on the signed-in user's grant.
export const inbox = new Hono<AppEnv>();

inbox.get("/threads", async (c) => {
  await requireUser(c);
  const r = await one(c).run(gmail.listAndViewEmailThreads, { body: { numberOfThreads: 10, label: "INBOX" } });
  if (!r.ok) return c.json(r, r.status as 403);
  const threads = (r.data.threads ?? []).map((t) => ({
    id: t.id ?? "",
    subject: t.messages?.[0]?.subject ?? "(no subject)",
    from: t.messages?.[0]?.sender ?? "",
    snippet: t.snippet ?? "",
  }));
  return c.json({ threads });
});

inbox.post("/reply", async (c) => {
  await requireUser(c);
  const { to, subject, text } = await c.req.json<{ to: string; subject: string; text: string }>();
  const r = await one(c).run(gmail.sendEmail, { body: { to, subject, body: text } });
  if (!r.ok) return c.json(r, r.status as 403);
  return c.json({ sent: true });
});

import { Hono } from "hono";
import type { AppEnv } from "./env";
import { inbox } from "./inbox";
import { oneRoutes } from "./one/connect";

// The app's API. Runtime-neutral Hono: server/worker.ts runs it on Workers,
// api/[[...route]].ts on Vercel. Add routes below the One routes.

const app = new Hono<AppEnv>();

app.get("/api/health", (c) => c.json({ ok: true, app: "acme-tasks" }));

// Sign in with One, the grant, and /api/one/health. Do not edit.
app.route("/api/one", oneRoutes);

// App routes go here. Routes that call one(c).run start with requireUser(c).
app.route("/api/inbox", inbox);

app.notFound((c) => c.json({ error: { code: "not_found", message: `No route for ${c.req.path}` } }, 404));

app.onError((err, c) => {
  console.error(err);
  return c.json({ error: { code: "server_error", message: err.message } }, 500);
});

export default app;
